DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[WorkOrder]([WorkOrderID],[ProductID],[OrderQty],[StockedQty],[ScrappedQty],[StartDate],[EndDate],[DueDate],[ScrapReasonID],[ModifiedDate],LoadBatchID) SELECT S.[WorkOrderID],S.[ProductID],S.[OrderQty],S.[StockedQty],S.[ScrappedQty],S.[StartDate],S.[EndDate],S.[DueDate],S.[ScrapReasonID],S.[ModifiedDate],@B FROM ssis_flow.Delta_WorkOrder S;
INSERT stg.[WorkOrder]([WorkOrderID],[ProductID],[OrderQty],[StockedQty],[ScrappedQty],[StartDate],[EndDate],[DueDate],[ScrapReasonID],[ModifiedDate],LoadBatchID) SELECT [WorkOrderID],[ProductID],[OrderQty],[StockedQty],[ScrappedQty],[StartDate],[EndDate],[DueDate],[ScrapReasonID],[ModifiedDate],@B FROM etl_raw.[WorkOrder];
INSERT etl_v2.SourceChange SELECT @B,N'Production.WorkOrder','I',@Next,(SELECT R.[WorkOrderID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[WorkOrder] R;
END ELSE BEGIN
SELECT [WorkOrderID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_WorkOrder FROM ssis_flow.Delta_WorkOrder;
INSERT etl_v2.SourceChange SELECT @B,N'Production.WorkOrder',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[WorkOrderID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_WorkOrder C LEFT JOIN etl_raw.[WorkOrder] R ON R.[WorkOrderID]=C.[WorkOrderID];
DELETE R FROM etl_raw.[WorkOrder] R JOIN #CT_WorkOrder C ON R.[WorkOrderID]=C.[WorkOrderID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[ProductID]=S.[ProductID],R.[OrderQty]=S.[OrderQty],R.[StockedQty]=S.[StockedQty],R.[ScrappedQty]=S.[ScrappedQty],R.[StartDate]=S.[StartDate],R.[EndDate]=S.[EndDate],R.[DueDate]=S.[DueDate],R.[ScrapReasonID]=S.[ScrapReasonID],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[WorkOrder] R JOIN #CT_WorkOrder C ON R.[WorkOrderID]=C.[WorkOrderID] JOIN ssis_flow.Delta_WorkOrder S ON S.[WorkOrderID]=C.[WorkOrderID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[WorkOrder]([WorkOrderID],[ProductID],[OrderQty],[StockedQty],[ScrappedQty],[StartDate],[EndDate],[DueDate],[ScrapReasonID],[ModifiedDate],LoadBatchID) SELECT S.[WorkOrderID],S.[ProductID],S.[OrderQty],S.[StockedQty],S.[ScrappedQty],S.[StartDate],S.[EndDate],S.[DueDate],S.[ScrapReasonID],S.[ModifiedDate],@B FROM #CT_WorkOrder C JOIN ssis_flow.Delta_WorkOrder S ON S.[WorkOrderID]=C.[WorkOrderID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[WorkOrder] R WHERE R.[WorkOrderID]=S.[WorkOrderID]);
INSERT stg.[WorkOrder]([WorkOrderID],[ProductID],[OrderQty],[StockedQty],[ScrappedQty],[StartDate],[EndDate],[DueDate],[ScrapReasonID],[ModifiedDate],LoadBatchID) SELECT R.[WorkOrderID],R.[ProductID],R.[OrderQty],R.[StockedQty],R.[ScrappedQty],R.[StartDate],R.[EndDate],R.[DueDate],R.[ScrapReasonID],R.[ModifiedDate],@B FROM etl_raw.[WorkOrder] R JOIN #CT_WorkOrder C ON R.[WorkOrderID]=C.[WorkOrderID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;